-- INSERT scripts for Volcano table
-- Source: Servicio Geológico Colombiano (SGC), Subdirección de Volcanología.
--         https://www.sgc.gov.co/volcanes  (machine-readable feed:
--         https://archive.sgc.gov.co/volcanos/volcanos.json — 24 volcanoes).
-- Dataset contributed in https://github.com/Mteheran/api-colombia/issues/201
--
-- Validation performed before seeding:
--   * All 24 DepartmentId / CityId pairs checked against the live api-colombia
--     data: every id exists and City.DepartmentId always matches DepartmentId.
--   * Name, Latitude and Longitude match the SGC feed exactly for all 24 records.
--   * Elevation and coordinates cross-checked against the Smithsonian Global
--     Volcanism Program (Holocene volcanoes WFS).
--
-- Corrections applied on top of the SGC feed (documented deviations):
--   * Elevation of Cerro Machín (2750), Nevado del Ruiz (5321) and Paramillo del
--     Quindío (4700). The SGC feed publishes 4487 / 4895 / 4715 for these three,
--     which are exactly their latitude x 1000 — a data-entry slip in the source.
--     The replacement values come from the Smithsonian GVP (2749 / 5279) and, for
--     Paramillo del Quindío, from the SGC's own description ("altura aproximada
--     de 4700 m").
--   * Campo volcánico Guamuez-Sibundoy: Putumayo/Sibundoy -> Nariño/Pasto. The
--     SGC description places it in the "corregimiento del Encano, municipio de
--     Pasto"; the published coordinates fall inside Pasto.
--   * Nevado de Santa Isabel: Risaralda/Pereira -> Tolima/Murillo. Risaralda is
--     not among the departments the SGC lists for this volcano ("Caldas,Tolima")
--     and the published coordinates fall inside Murillo.
--
-- Volcanoes on a municipal or departmental boundary are assigned a single
-- representative municipality, following the pattern used by every other
-- resource in this API (no many-to-many location relations).
--
-- ActivityLevel is the SGC alert level at the time the dataset was captured
-- (2026-08); it is not a live value.

INSERT INTO "Volcano" ("Id", "Name", "Description", "Elevation", "Latitude", "Longitude", "VolcanoType", "ActivityLevel", "ImageUrl", "DepartmentId", "CityId") VALUES
(1, 'Campo volcánico Guamuez-Sibundoy', 'El Campo volcánico monogenético Guamuez-Sibundoy se localiza a 20 km al oriente de la ciudad de Pasto (Nariño) y a 29,6 km al occidente del municipio de Santiago (Putumayo), en el corregimiento del Encano, municipio de Pasto, en las coordenadas geográficas 1°06′ N - 77°09′ W. El acceso a las estructuras que conforman este campo realiza por la vía principal que comunica Pasto, capital de Nariño, con el departamento del Putumayo (ruta nacional 10), la cual transita por el corregimiento del Encano; de allí se toma una vía secundaria que lleva a un importante centro turístico, el cual tiene un puerto fluvial donde parten pequeños botes que la navegan. Esta es una de las formas de transporte para acceder a los edificios volcánicos que se ubican en el lado oriental de la laguna de La Cocha. Otra vía de acceso a los volcanes, es por medio de un camino que comunica las veredas del sector oriental de la laguna. Para acceder a los volcanes del Alto Putumayo se continua por la ruta nacional 10 hasta el municipio de Santiago y de allí se toma una vía secundaría hasta la vereda Muchivioy, sector de asentamiento de la comunidad Inga Manoy', 2700, 1.1133222, -77.1194999, 'Campo monogenético', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/sibundoy.jpg', 22, 769),
(2, 'Complejo Volcánico Chiles-Cerro Negro', 'El Complejo Volcánico Chiles-Cerro Negro se edifica en intersecciones de la falla Chiles-Cerro Negro, con las fallas Chiles-Cumbal y Cerro Negro-Nasate, sobre un basamento representado por una secuencia potente de lavas pliocénicas, depositadas sobre rocas volcanosedimentarias de la formación Nariño, a su vez, depositadas sobre rocas de los grupos Dagua y Diabásico, así como sobre metamorfitas del grupo Cajamarca. El edifico actual del Chiles esta conformado fundamentalmente por varios episodios de flujos de lava y el volcán Cerro Negro por flujos de lava y de piroclástos. De acuerdo con análisis químicos y petrográficos, los productos del Complejo Volcánico de Chiles-Cerro Negro se clasifican como andesitas de d', 4470, 0.83137, -77.96775, 'Estratovolcán o Volcán compuesto', 'Alerta amarilla', 'https://archive.sgc.gov.co/volcanos/images/cerro_negro.jpg', 22, 779),
(3, 'Volcán Azufral', 'El volcán Azufral es un estrato-volcán, con un diámetro del cráter estimado en 3 Km, en donde se encuentra la laguna cratérica llamada Laguna Verde, no registra la presencia de glaciares, y presenta el registro de depósitos asociados con flujos de lava, flujos piroclásticos de gran magnitud y depósitos de caída (cenizas y pumitas). En la actualidad existe actividad fumarólica y algunas manifestaciones sísmicas. Se dispone de algunos registros sísmicos de eventos de Largo-periodo y algunas señales Volcano-tectónicas. Debido a la existencia de páramos en la cima se propicia condiciones para el nacimiento de fuentes de agua que esencialmente exhiben un patrón radial de drenaje', 4070, 1.085, -77.717, 'Estratovolcán o Volcán compuesto', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/azufral.jpg', 22, 823),
(4, 'Volcán Cerro Bravo', 'La historia geológica del volcán Cerro Bravo probablemente comenzó hace 50.000 años, cuando se construyó un edificio antiguo, sobre el cual, en los últimos 14.000 años, se ha estado construyendo el edificio moderno. Clasificación: Es un estratovolcán caldérico activo con dos calderas concatenadas de 1.5 y 1.0 km de diámetro y muy violento. Actualmente está en reposo. Fuera del atractivo paisajístico y las fuentes termales, su cercanía a una carretera importante convierte a este volcán en un potencial geoturístico a aprovechar.', 4000, 5.091, -75.292, 'Complejo de domos', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/cerro_bravo.jpg', 30, 1042),
(5, 'Volcán Cerro España', 'El complejo Cerro España fue descrito por primera vez por la Central Hidroeléctrica de Caldas S.A. (1983) como una estructura formada por una caldera de 2,5 km de diámetro que contiene domos que conforman el Cerro España en sentido estricto, así como a varios centros volcánicos ubicados en el borde W de la caldera, identificados como Cerro Arenero, Cerros de Alsacia y otros volcanes. El complejo volcánico Cerro España se considera activo con base en su registro estratigráfico de edad del Holoceno, su sismicidad y actividad fumarólica, esta última asociada al campo fumarólico al sur del lago Otún', 4560, 4.7531139, -75.3740833, 'No determinado', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/cerro_espana.jpg', 30, 1059),
(6, 'Volcán Cerro Machín', 'Este volcán es llamado Machín, Cerro Machín, Alto de Machín y El Hoyo. El acceso se puede hacer por una vía que parte desde la población de Cajamarca y llega al Corregimiento de Toche, una segunda opción parte del sitio denominado Boquerón, salida de Ibagué hacia Armenia, pasando por los corregimientos de Tapias y Toche; y la tercera que inicia desde el casco urbano de Salento en el Departamento del Quindío y comunica con el corregimiento de Toche. Edad: El volcán Machín restringe su actividad al Holoceno, como puede ser observado en la tabla siguiente. Su edificio está fundado directamente sobre basamento muy antiguo y allí no hay registro geológico de actividad volcánica neógena previa Departamento: Tolima Municipio: Jurisdicción del corregimiento de Toche, municipio de Ibagué El volcán Cerro Machín está construyéndose sobre un basamento metamórfico paleozoico (Grupo Cajamarca), en cruce de fallas de dirección NNE con otras de tipo transversal. Su historia geológica es muy corta y se caracteriza por su alta explosividad, explicada por la composición dacítica de los productos volcánicos emitidos. Tales productos son domos, tres de los cuales taponan el conducto volcánico, depósitos de flujos piroclásticos de ceniza y pómez, de ceniza y bloques y de oleadas piroclásticas, así como depósitos provenientes de flujos de lodo (lahares).', 2750, 4.487, -75.386, 'Complejo anillo piroclástico-domo', 'Alerta amarilla', 'https://archive.sgc.gov.co/volcanos/images/cerro_machin_kl3d0OI.jpg', 30, 1069),
(7, 'Volcán Cumbal', 'El complejo volcánico de Cumbal se encuentra localizado en el departamento de Nariño, al occidente de la población de Cumbal, 79 km al sur-occidente de la ciudad de Pasto y 585 km al sur-occidente Santafé de Bogotá, en las coordenadas geográficas de 0° 57'' N y 77° 52'' W. El acceso a la cima se realiza por un carreteable que parte de Cumbal, hasta la vereda La Ortiga y de allí se desprende un amplio camino de herradura hasta las cercanías de los dos cráteres principales, a los cuales se debe llegar a pie; el recorrido toma como mínimo cuatro horas.', 4764, 0.956, -77.885, 'Estratovolcán o Volcán compuesto', 'Alerta amarilla', 'https://archive.sgc.gov.co/volcanos/images/cumbal.jpg', 22, 779),
(8, 'Volcán Doña Juana', 'El Volcán Doña Juana localizado en el nor-oriente del Departamento de Nariño, es considerado como uno de los volcanes activos y peligrosos de Colombia; su registro de actividad histórica nos remonta al período 1897-1936, con la ocurrencia de varias erupciones explosivas que infortunadamente causaron la muerte de más de 100 personas y grandes pérdidas económicas en su región de influencia. El volcán Doña Juana es considerado como un estrato volcán andesítico, con un diámetro del cráter cercano a 4 Km, sin glaciares, con registro de depósitos asociados con flujos de lava, flujos piroclásticos y cenizas; los riesgos que la actividad de este volcán pueden acarrear se relacionan con ocurrencia de flujos piroclásticos, flujos de lodo o lahares y caídas de ceniza. El 20 de junio de 2008 se instaló una estación sísmica denominada Lavas, dotada de un sensor triaxial de corto periodo, en un punto distante 4 Km al sur-occidente de la cima volcánica. Para que las señales captadas por esta estación lleguen en tiempo real a la sede del Observatorio Vulcanológico y Sismológico de Pasto (OVSP) para su procesamiento y análisis, se cuenta con dos puntos de repetición, de manera que la señal que sale de la estación Lavas pasa por las repetidoras de Morasurco y Cruz de Amarillo antes de llegar al OVSP. En la región de influencia de Doña Juana, Ánimas y Petacas, se localizan varios municipios entre los que se mencionan a La Cruz, San Pablo, Belén, San Bernardo, San José. En siglos pasados, estas poblaciones correspondían a pequeños caseríos; sin embargo, con el tiempo se ha ido incrementado el número de habitantes así como la cantidad de poblaciones asentadas en sus faldas.', 4160, 1.498, -76.939, 'Estratovolcán o Volcán compuesto', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/donajuana.jpg', 22, 826),
(9, 'Volcán El Escondido', 'Es un volcán monogenético cuaternario recientemente identificado por el SGC en la cordillera Central de Los Andes colombianos. Se localiza en el departamento de Caldas, en el límite del Parque Nacional Natural Selva de Florencia, a unos 50 km al noreste del volcán Cerro Bravo, formando parte del segmento norte de volcanes activos del país. El centro poblado de Florencia está construido en el flanco norte del volcán, desde el borde de su cráter. El acceso a esta población y al volcán se realiza por la antigua vía a Sonsón (Antioquia) que comunica las poblaciones de La Dorada y Florencia.', 1650, 5.5157, -75.0481116, 'No determinado', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/volcan_escondido.jpg', 8, 357),
(10, 'Volcán Galeras', 'El volcán Galeras se localiza en el Departamento de Nariño, aproximadamente a 9 km al occidente de la Ciudad de San Juan de Pasto, capital de este departamento, en las coordenadas 1° 13'' 43,8" de latitud norte y 77° 21'' 33,0" de longitud oeste y con una altura de 4276 msnm. De acuerdo con el Catálogo de Volcanes Activos del Mundo (CAVW) de la Asociación Internacional de Vulcanolgía y Química del Interior de la Tierra (IAVCEI), su código es el 1501-08. Los indígenas Quillacingas dieron el nombre de "Urcunina" (Montaña de Fuego) al volcán de Pasto, hoy conocido "volcán Galeras"; llamado así, por los primeros conquistadores españoles, por su semejanza con las Galeras o barcos que con sus velas navegaban en aquel entonces por el Mediterráneo. Para su acceso tiene una carretera de unos 23 km en regular estado, que va de la ciudad de San Juan de Pasto (sector de Anganoy) hasta la cima y una vía circunvalar de aproximadamente 117,5 km, parcialmente pavimentada que lo rodea en su totalidad comunicando a San Juan de Pasto con los pueblos de Catambuco, Yacuanquer, Consacá, Sandoná, La Florida, Nariño y Genoy, en sentido horario. Adicionalmente, se cuenta con un camino no transitable vehicularmente llamado el Camino Real que une a San Juan de Pasto con Consacá, población localizada en el extremo opuesto al occidente del volcán, camino que atraviesa a media falda la montaña por el costado norte.', 4276, 1.221, -77.359, 'Estratovolcán o Volcán compuesto', 'Alerta amarilla', 'https://archive.sgc.gov.co/volcanos/images/galeras.jpg', 22, 769),
(11, 'Volcán Guadalupe', 'El complejo de domos Guadalupe se encuentra localizado en el nororiente del departamento de Caldas, entre los municipios de Manzanares, Pensilvania y Marquetalia. A esta estructura se accede desde la carretera Manizales-Mariquita, en el desvío, a la altura del sector de Petaqueros hacia la población de Manzanares. A la base del complejo de domos y rodeándolo, se encuentran las carreteras Manzanares-Pensilvania y Manzanares-Marquetalia. También se puede acceder desde la vía La Dorada-Marquetalia. El acceso al domo principal se realiza desde la carretera Manzanares-Marquetalia por un camino de peregrinación. A algunos de los otros domos se puede acceder por caminos hacia propiedades rurales', 2565, 5.2870833, -75.130233, 'Complejo de domos', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/guadalupe.JPG', 8, 346),
(12, 'Volcán Las Ánimas', 'Las Ánimas se encuentra situado al suroccidente del país, se emplaza en el Macizo Colombiano, en el departamento de Nariño, más exactamente en límites con el departamento del Cauca. Con una altura de 4300 msnm, Las Ánimas se localiza a unos 11 Km al noreste del volcán Doña Juana y a 12 Km al suroeste del volcán Petacas, en su zona de influencia se ubican los municipios La Cruz, San Pablo, Las Mesas, La Unión, Colón, San Bernardo (Nariño), y Florencia, Bolívar y Santa Rosa (Cauca)', 4200, 1.56697, -76.87008, 'Estratovolcán o Volcán compuesto', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/las_animas.jpg', 22, 792),
(13, 'Volcán Nevado de Santa Isabel', 'El volcán nevado de Santa Isabel, se encuentra localizado en los límites de los departamentos de Risaralda, Caldas y Tolima, en las coordenadas geográficas 4° 47'' N y 75° 24'' O, a una distancia de 140 km al noreste de Bogotá y a 33 km al sureste de Manizales. El acceso al volcán se realiza por la carretera Manizales - Murillo, tomando el mismo desvío que hacia el Ruiz, en Brisas, hasta la altura de La Olleta; de allí se desvía hacia el sur (derecha), hasta la Hacienda Potosí; luego se hace otro tramo por un carreteable sólo utilizable en verano y a pie hacia el volcán. También, se puede acceder al Nevado de Santa Isabel utilizando la carretera y camino que, desde Pereira, llevan a la Laguna del Otún. El Complejo de Domos del Santa Isabel fue construido sobre un basamento metamórfico del Paleozoico y de rocas vulcano-sedimentarias del Mesozoico, intruido por el Batolito de El Bosque de edad terciaria; se encuentra sobre la falla de Palestina, en sitios de intersección con fallas transversales . En el complejo dómico han sido determinados antiguos flujos de lava de composición andesítica de dos piroxenos y unas mas recientes que las suprayacen (flujos de lava en bloques, provenientes principalmente de los domos actuales), también de composición andesítica. Adicionalmente, han sido identificados tres domos, denominados Norte, Centro y Sur, a los cuales se les puede agregar otros cuatro, ubicados al S del edificio principal, llamados Alsacia Norte, Alsacia Sur, Arenero Norte y Arenero Sur. También, en las partes somitales han sido encontrados, debajo de los flujos de lava originados en los domos actuales, principalmente del domo Norte, depósitos de flujos piroclásticos de ceniza y bloques, de escoria y de ceniza y pómez.', 4965, 4.8049889, -75.3732333, 'Complejo de domos', 'Alerta amarilla', 'https://archive.sgc.gov.co/volcanos/images/nevado_santa_isabel.jpg', 30, 1047),
(14, 'Volcán Nevado del Huila', 'El Complejo Volcánico Nevado del Huila (CVNH) conocido comúnmente como el Volcán Nevado del Huila, hace parte del Parque Nacional Natural del mismo nombre que está localizado entre los departamentos de Cauca, Huila y Tolima, en las coordenadas 2° 55'' N y 76° 03'' W a una distancia de 285 km al SW de Bogotá, 85 km al NE de Popayán y 60 km al WSW de Neiva . Su altura máxima, el Pico Central (5 364 m s.n.m.), corresponde al punto más alto de la cordillera Central y de los Andes en Colombia. El Volcán Nevado del Huila es un complejo volcánico activo conformado por estratovolcanes y varios domos (en el Pico Sur). Su actividad ha sido dominantemente efusiva, pero en su desarrollo más reciente ha generado flujos piroclásticos producidos por colapsos y/o explosiones de domos. El Complejo Volcánico se ha formado a través de dos edificios sobrepuestos, llamados Pre-Huila y Huila. Este último se desarrolló en dos etapas: Edificio Antiguo y Edificio Actual. Los productos emitidos por este Complejo Volcánico han sido principalmente de composición andesítica. El basamento de este Complejo Volcánico está conformado por rocas de diferente litología y edad, entre las que se destacan rocas metamórficas del Precámbrico (Neis de Quintero) y del Paleozoico (esquistos del Complejo Cajamarca), rocas plutónicas del Jurásico (cuarzodioritas y granodioritas del Batolito de La Plata, que conforman cerca del 60% del basamento) y rocas metasedimentarias del Cretácico (pizarras, fillitas y meta-areniscas). Sobre este basamento cruzan fallas con dirección general NNE, entre las que se encuentran las de Moras Oeste, Moras Este, Símbola, Inzá y Tálaga, y otras orientadas más hacia el NE, como las de Tóez y Calambayú.', 5364, 2.924, -76.029, 'Estratovolcán o Volcán compuesto', 'Alerta amarilla', 'https://archive.sgc.gov.co/volcanos/images/nevado_del_huila.jpg', 11, 440),
(15, 'Volcán Nevado del Ruiz', 'En época precolombina se le llamaba Cumanday (Cerro Blanco), Tabuchía (Candela o fuego) o Tama (Padre Mayor o Grande). El acceso al volcán se hace partiendo de la ciudad de Manizales, se toma la vía a Bogotá y en el sector conocido como el 8 o La Esperanza se desprende la carretera que conduce a la población de Murillo, de la cual se desprende un carreteable en el sitio conocido como Brisas que llega hasta el borde de la nieve. Para ingresar al Parque Nacional Natural de los Nevados se requiere pagar una pequeña suma de dinero al Ministerio del Medio Ambiente, con el fin de darle mantenimiento y recuperación al Parque; así mismo hay que contratar un guía que acompañará y dará los comentarios pertinentes para desarrollar un turismo neta y exclusivamente didáctico y ecológico. Está construido sobre el mismo basamento del Cerro Bravo, en la compleja intersección de cuatro grupos de fallas, donde las más significativas son Palestina y Termales - Villamaría. Han ocurrido tres estadios denominados Ruiz Ancestral, Ruiz Viejo y Ruiz que incluyen la construcción y destrucción alternada de tres edificios, generando lavas, depósitos de flujos piroclásticos, de oleadas piroclásticas, de avalanchas de escombros, de piroclastos de caída y de lahares y domos. Sus productos son fundamentalmente andesitas de dos piroxenos, con variaciones a dacitas y andesitas basálticas.', 5321, 4.895, -75.321, 'Estratovolcán o Volcán compuesto', 'Alerta amarilla', 'https://archive.sgc.gov.co/volcanos/images/nevado_del_ruiz.jpg', 30, 1047),
(16, 'Volcán Nevado del Tolima', 'El principal y más fácil acceso al volcán se realiza partiendo desde la ciudad de Ibagué a lo largo de un carreteable que lleva hasta el sector de El Silencio, pasando por los corregimientos de Restrepo, Pastales y Juntas; de allí en adelante se desprenden varios caminos a pie, los cuales conducen hasta sus faldas y la cima, siendo más utilizado aquel que pasa por las Termales de El Rancho. El Nevado del Tolima se formó sobre un basamento de vulcanitas mio-pleistocénicas y rocas cristalinas del Batolito de El Bosque y del Grupo de Cajamarca. La formación del Tolima incluye dos etapas ocurridas en el Cuaternario, una inicial caldérica (Tolima antiguo) y otra de construcción del actual cono (Tolima moderno). Los productos típicos del volcán han sido catalogados como andesitas de dos piroxenos; se trata de lavas (masivas y en bloques) y depósitos de flujos piroclásticos de ceniza y bloques y de escoria, y de caída de piroclastos. El hecho de ser un volcán nevado ha incrementado las condiciones favorables para la generación de flujos de lodo (lahares).', 5215, 4.659, -75.329, 'Estratovolcán o Volcán compuesto', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/nevado_del_tolima.jpg', 30, 1069),
(17, 'Volcán Paramillo de Santa Rosa', 'El VPSR es el más occidental de los volcanes del Complejo Volcánico Cerro Bravo-Cerro Machín (CVCBCM) y está desplazado unos 10 km hacia el occidente con respecto al eje de la Cordillera Volcánica Central, hallándose en correspondencia con la Laguna del Otún y la parte meridional del Nevado Santa Isabel. Para llegar al paramillo se puede tomar la vía que desde el municipio de Santa Rosa de Cabal conduce hasta el sitio, tras recorrer aproximadamente 8 km en dirección suroriental. El basamento sobre el cual se levanta este estratovolcán, el cual cubre una zona de 160 km2, está constituido por el Complejo Metamórfico Paleozoico del Cajamarca. Sus lavas, de naturaleza porfirítica andesítica, se caracterizan por una abundante cantidad de plagioclasa zonada (An43-39), augita, hiperstena, horblenda parda y óxidos opacos en una matriz intersertal hialina. La parte superior de la estructura está disectada por diques, y presenta una marcada alteración hidrotermal.', 4600, 4.7914167, -75.4662833, 'Estratovolcán o Volcán compuesto', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/paramillo_de_santa_rosa.jpg', 26, 909),
(18, 'Volcán Paramillo del Cisne', 'El paramillo del Cisne-Morro Negro está localizado en la Cordillera central de Colombia entre los complejos volcánicos del Nevado del Ruiz (al norte) y el Nevado de Santa Isabel (al sur). Estos complejos se encuentran en la vía que conduce a la Laguna del Otún en el Parque Nacional Natural de los Nevados. El acceso desde Manizales, se hace tomando la vía que conduce a Bogotá. En el kilómetro 27, sector de la Esperanza (conocido como sector del ocho), se toma el desvío que lleva a la población de Murillo, en el sector conocido como Brisas se encuentra la vía al refugio de Brisas (acceso al Parque Nacional Natural de los Nevados) y posteriormente se toma el desvío a la Laguna del Otún. Para ingresar al Parque Nacional Natural de los Nevados se requiere pagar suma pequeña de dinero al Ministerio del Medio Ambiente, con el fin de darle mantenimiento y recuperación al Parque. Así mismo debe contratarse el servicio de un guía especializado de montaña que acompañará y dará los comentarios pertinentes para desarrollar un turismo neta y exclusivamente didáctico y ecológico. Desde Bogotá, se debe tomar la vía Honda - Manizales hasta el sector denominado La Esperanza y allí se debe continuar la ruta hacia el Parque.', 4700, 4.843, -75.352, 'Domo colada', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/paramillo_del_cisne.jpg', 8, 361),
(19, 'Volcán Paramillo del Quindío', 'El Paramillo del Quindío está situado sobre el eje de la Cordillera Central en el límite de los departamentos del Tolima, Quindío y Risaralda en las coordenadas geográficas 4.42°20" de latitud norte y 75.23°26" de longitud oeste. Corresponde a una estructura volcánica con una altura aproximada de 4700 m, caracterizada por una morfología madura heredada de la acción glaciar. La parte central del edificio corresponde a una concavidad abierta hacia el suroeste, con una amplitud de cerca de 2 km formada por un posible colapso del edificio en este sector, es probable que la acción erosiva del hielo se haya impuesto sobre una pequeña depresión caldérica preexistente. La parte central del edificio volcánico ha sido afectado por intensa actividad hidrotermal, los flujos de lava presentan fuerte alteración y mineralización, actualmente no se observan evidencias de esta actividad por la ausencia de manifestaciones termales en el área.', 4700, 4.715, -75.389, 'Estratovolcán o Volcán compuesto', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/paramillo_del_quindio.jpg', 25, 894),
(20, 'Volcán Puracé', 'El volcán Puracé se encuentra localizado en el departamento del Cauca, en las coordenadas geográficas 2°19''01N y 76°23''53W, a una distancia de 26 km al SE de la ciudad de Popayán. Hace parte de la Cadena Volcánica de Los Coconucos, compuesta por 15 centros eruptivos alineados con una orientación N40°W, siendo el Puracé el más joven y septentrional de la Cadena. Su edificio tiene forma de un cono truncado, presenta un cráter interno y otro externo concéntricos de 500 y 900 m de diámetro, respectivamente. La actividad fumarólica se concentra en el interior del cráter, principalmente en una gran grieta que atraviesa el fondo y en un importante campo fumarólico en el flanco externo norte del volcán (“Fumarola Lateral”). El basamento está constituido por rocas volcánicas del Terciario Superior-Cuaternario y localmente por rocas volcánicas del Cretácico. El volcán Puracé se encuentra construido sobre un edificio antiguo (Pre-Puracé), el cual se desarrolló en el borde de una caldera (Chagartón). Los productos principales del volcán son piroclastos, intercalados con coladas de lava, generalmente de composición andesítica. El monitoreo continuo de la actividad del volcán se inició en octubre de 1986; a partir de 2007, se empezó una etapa de densificación de la red de monitoreo y en la actualidad se cuenta con una red de 32 estaciones para el monitoreo de la actividad volcánica; en estas estaciones hay instalados 65 sensores para medir parámetros de la actividad sísmica, deformación de la superficie del volcán, emisiones de gases, temperatura, ondas acústicas, potencial eléctrico, entre otros.', 4650, 2.313, -76.395, 'Compuesto', 'Alerta naranja', 'https://archive.sgc.gov.co/volcanos/images/purace.jpg', 11, 426),
(21, 'Volcán Romeral', 'El Volcán Romeral está ubicado en la zona central de Colombia en el departamento de Caldas, el Acceso se puede realizar por vía carreteable qué comunica a los municipios de Neira y Marulanda. Corresponde a una geoforma de forma cónica de base amplia con un patrón de drenaje dendrítico de baja densidad de dispersión radial, donde nacen cuatro cuencas hidrográficas correspondientes a los ríos Chamberí, Tapias y Guacaíca los cuales drenan sus aguas hacia el departamento de Caldas y el río Guarinó hacia el departamento del Tolima.', 3858, 5.206, -75.364, 'No determinado', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/romeral.jpg', 8, 349),
(22, 'Volcán San Diego', 'San Diego es un volcán conformado por una caldera (Laguna de San Diego) y un cono de tipo estratovolcano, Morro de San Diego, construido al NE del margen de la caldera. Una de las características principales de la laguna es la presencia de aguas termales, que hacen que la temperatura del agua sea aproximadamente 30 °C en el centro de ésta y se incremente hacia el norte de la misma. Esporádicamente se observan emisiones gaseosas. Ha sido catalogado geomorfologicamente como el Maar de San Diego, cuyo cráter tiene aproximadamente 3 km de diámetro y está cortado por fallas Norte-Sur, pertenecientes al sistema de fallas de Palestina (Feininger, 1970). En él se localiza una laguna que tiene aproximadamente 250 m bajo el borde del cráter con una profundidad de más de 60 m en el centro de la misma. El cono volcánico de San Diego tiene una altitud de 1150 m, es decir, 450 m por encima del lago. Este cono tiene una pequeña colina hacia el norte, la cual se encuentra recubierta por depósitos picroclásticos y al parecer están aislados del lago por un lineamiento NO, que divide en dos el límite del evento volcánico. Hacia la parte NE se encuentra el cono de San Diego y el pequeño cono adventicio en la parte sur del lago. Entre sus productos principales se tienen los depósitos de una erupción freatomagmática datada en 18.700 ± 10.000 años que se caracterizan por la abundancia de material lítico, además de la presencia de pómez y cristales (Toro, 1989).', 850, 5.649, -74.96, 'Complejo de anillo piroclástico –Maar. Cono de toba intracratérica', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/san_diego.jpg', 8, 357),
(23, 'Volcán Sotará', 'El CVS se encuentra ubicado en la Cordillera Central de Colombia, en el límite entre los departamentos de Cauca y Huila, localizado a 37 km al SE de la ciudad de Popayán (departamento del Cauca) y a 400 km al SW de la ciudad de Bogotá D.C. La población más cercana es el resguardo indígena de Rioblanco, localizado a 10 km al WSW del volcán Sotará, con 1500 habitantes aproximadamente. Otras poblaciones son Chapa, a 11 km al NW, Pueblo Quemado y Guachicono, al SW. Los drenajes más importantes alrededor del volcán son el río Quilcacé y la quebrada Las Flautas al NW, los ríos Blanco, Negro y Guachicono al WSW y el río Majuas al SE. El estratovolcán antiguo (Pre-Sotará) evolucionó hasta un estado caldérico; los volcanes Cerro Negro y Cerro Azafatudo se desarrollaron en el flanco NW del edificio de Pre-Sotará, mientras que los volcanes Cerro Gordo y Sotará representan un vulcanismo resurgente posterior al colapso caldérico, construyéndose, el primero de ellos en el borde S y el segundo al interior de la caldera. El Complejo Volcánico Sotará (CVS) incluye los remanentes de un estratovolcán antiguo (Pre-Sotará) sobre el cual se construyó el volcán Sotará (actualmente activo, con una altitud máxima cercana a los 4420 msnm) y otros centros eruptivos (Cerro Negro, Cerro Azafatudo y Cerro Gordo)', 4420, 2.107, -76.591, 'Estratovolcán o Volcán compuesto', 'Alerta amarilla', 'https://archive.sgc.gov.co/volcanos/images/sotara.jpg', 11, 430),
(24, 'Volcán Sucubún', 'El volcán Sucubún está localizado entre los departamentos de Cauca y Huila, en las coordenadas 2° 01'' N y 76° 34'' W a una distancia de 400 km al SW de Bogota y 47 km al SE de Popayán, su máxima altura es de 4100 m s.n.m. (figura 2). La población más cercana es Guachicono Frío (resguardo indígena), localizado a 11 km al W del volcán Sucubún. Otras poblaciones en los alrededores del volcán son Río Blanco (Cauca) a 13 km al NW, Paispamba (Cauca) a 26 km al NNW, Paletará (Cauca) a 23 km NE, San Agustín (Huila) a 37 km SE y Puerto Quinchana (Huila) a 20 al SE. El volcán Sucubún se ubica en el suroccidente colombiano, sobre la Cordillera Central. Su máxima altitud es de 4100 m s.n.m. Se encuentra a 10 km al SSE del volcán Sotará. Este volcán, en su expresión joven presenta una forma dómica de 2,1 km de diámetro y se encuentra en el interior de los remanentes de dos estructuras volcánicas concéntricas más antiguas, que conformaban una antigua caldera externa y un cono destruido (figura 1). De acuerdo con trabajos geológicos preliminares de campo, así como con el apoyo de sensores remotos, ambos realizados por el SGC (Pulgarín et al., 2010), a estas estructuras volcánicas se le asocian depósitos de flujos de lava, potentes y extensas corrientes de densidad piroclástica concentradas y diluidas intercaladas con caídas piroclásticas, domos de lava y algunos lahares. ​', 4100, 2.018, -76.574, 'Caldera domo', 'Alerta verde', 'https://archive.sgc.gov.co/volcanos/images/sucubun.jpg', 11, 416);

